35	    @Test
36	    @DisplayName("同一成员并发不同 requestId 申请：仅唯一受理，其余冲突，无重复快照")
37	    void concurrentApplicationsOnlyOneAccepted() throws Exception {
38	        member("C1", "并发甲", LocalDate.of(2023, 9, 25), MemberStatus.RESIGNED);
39	        contribution("C1", ContributionType.PERSONAL, 50L, LocalDate.of(2024, 1, 1), "2024-01");
40	        contribution("C1", ContributionType.ENTERPRISE, 100L, LocalDate.of(2024, 1, 1), "2024-01");
41	
42	        ExecutorService pool = Executors.newFixedThreadPool(THREADS);
43	        CountDownLatch ready = new CountDownLatch(THREADS);
44	        CountDownLatch start = new CountDownLatch(1);
45	        List<Future<?>> futures = new ArrayList<>();
46	        AtomicInteger accepted = new AtomicInteger();
47	        AtomicInteger conflict = new AtomicInteger();
48	        List<String> acceptedPlanNos = java.util.Collections.synchronizedList(new ArrayList<>());
49	
50	        for (int i = 0; i < THREADS; i++) {
51	            final int idx = i;
52	            futures.add(pool.submit(() -> {
53	                ready.countDown();
54	                start.await();
55	                try {
56	                    PlanResponse plan = pensionService.applyPayout(new PayoutRequest(
57	                            "C1-REQ-" + idx, "C1", PayoutReason.RESIGN,
58	                            InstallmentType.LUMP_SUM, TODAY));
59	                    accepted.incrementAndGet();
60	                    acceptedPlanNos.add(plan.planNo());
61	                } catch (ApiException ex) {
62	                    if ("ACTIVE_PLAN_EXISTS".equals(ex.getCode())) {
63	                        conflict.incrementAndGet();
64	                    } else {
65	                        throw ex;
66	                    }
67	                }
68	                return null;
69	            }));
70	        }
71	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
72	        start.countDown();
73	        for (Future<?> f : futures) {
74	            f.get(30, TimeUnit.SECONDS);
75	        }
76	        pool.shutdown();
77	        assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
78	
79	        assertThat(accepted.get()).isEqualTo(1);
80	        assertThat(conflict.get()).isEqualTo(THREADS - 1);
81	        assertThat(acceptedPlanNos).hasSize(1);
82	        assertThat(countPlans()).isEqualTo(1L);
83	        // 缴费只被冻结到唯一一个计划一次，不存在重复计划引用
84	        assertThat(countWhere("SELECT COUNT(*) FROM contribution WHERE snapshot_plan_id IS NOT NULL"))
85	                .isEqualTo(2L);
86	        PlanResponse plan = pensionService.getPlan(acceptedPlanNos.get(0));
87	        assertThat(plan.vestedTotalCents()).isEqualTo(100L);
88	        assertThat(plan.unvestedReturnCents()).isEqualTo(50L);
89	    }
