172	
173	        assertThat(paid.get()).isEqualTo(1);
174	        assertThat(alreadyPaid.get()).isEqualTo(THREADS - 1);
175	        assertThat(successes).hasSize(1);
176	        assertThat(successes.get(0).replayed()).isFalse();
177	        assertThat(countLedger("MEMBER_PAYOUT")).isEqualTo(1L);
178	        assertThat(sumLedger("MEMBER_PAYOUT")).isEqualTo(100L);
179	        assertThat(countLedger("ENTERPRISE_RETURN")).isEqualTo(1L);
