188	        contribution("C4", ContributionType.PERSONAL, 100L, LocalDate.of(2024, 1, 1), "2024-01");
189	        PlanResponse plan = pensionService.applyPayout(new PayoutRequest(
190	                "C4-REQ", "C4", PayoutReason.RETIRE, InstallmentType.LUMP_SUM, TODAY));
191	
192	        ExecutorService pool = Executors.newFixedThreadPool(THREADS);
193	        CountDownLatch ready = new CountDownLatch(THREADS);
194	        CountDownLatch startLatch = new CountDownLatch(1);
195	        List<Future<PaymentResultResponse>> futures = new ArrayList<>();
196	        for (int i = 0; i < THREADS; i++) {
197	            futures.add(pool.submit(() -> {
198	                ready.countDown();
