226	    private long countPlans() {
227	        Long value = jdbcTemplate.queryForObject("SELECT COUNT(*) FROM payout_plan", Long.class);
228	        return value == null ? 0L : value;
229	    }
230	
231	    private long countWhere(String sql) {
232	        Long value = jdbcTemplate.queryForObject(sql, Long.class);
233	        return value == null ? 0L : value;
234	    }
235	
236	    private long countLedger(String movementType) {
237	        Long value = jdbcTemplate.queryForObject(
238	                "SELECT COUNT(*) FROM account_ledger WHERE movement_type = ?",
239	                Long.class, movementType);
240	        return value == null ? 0L : value;
241	    }
