243	    private long sumLedger(String movementType) {
244	        Long value = jdbcTemplate.queryForObject(
245	                "SELECT COALESCE(SUM(amount_cents),0) FROM account_ledger WHERE movement_type = ?",
246	                Long.class, movementType);
247	        return value == null ? 0L : value;
248	    }
249	}
