    private static final RowMapper<LateContributionEventRow> ROW_MAPPER = (rs, rowNum) -> new LateContributionEventRow(
            rs.getLong("id"),
            rs.getLong("member_id"),
            rs.getLong("contribution_id"),
            rs.getLong("claim_id"),
            rs.getLong("amount_cents"),
