        this.pensionService = pensionService;
    }

    /** 登记/更新成员（合成数据）。 */
    @PostMapping("/members")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void upsertMember(@Valid @RequestBody MemberUpsertRequest request) {
        pensionService.upsertMember(request);
    }

